pub fn idb_source_for_candidate(path: String) -> Option<String> {
    idb_candidates()
        .iter()
        .cloned()
        .fold(None, |found: _, candidate: Rc<IdbCandidate>| {
            match found.clone() {
                Some(_) => found.clone(),
                None => match (candidate.file.clone() == path.clone()) {
                    true => Some(candidate.source.clone()),
                    false => None,
                },
            }
        })
}

